import{_ as e,c as r,o,a4 as t}from"./chunks/framework.BU14wsQo.js";const n="/ai/daily/2026-06-18/news_01kvccw0q1exzb9jqsccgft665.avif",i="/ai/daily/2026-06-18/news_01kvcbmb93exzb9jkz2vyxkwvq.avif",l="/ai/daily/2026-06-18/news_01kvccvm8jexzb9jqh9ejytq6z.avif",s="/ai/daily/2026-06-18/news_01kvcbmhj5exzb9jmbt24x09gr.avif",c="/ai/daily/2026-06-18/news_01kvcbncxbexzb9jp1bcv8mppd.avif",h="/ai/daily/2026-06-18/news_01kvcbnem2exzb9jpbnnk8qmdy.avif",p="/ai/daily/2026-06-18/news_01kvcbmpk4exzb9jmxa6pa03b0.avif",d="/ai/daily/2026-06-18/news_01kvcbmrhcexzb9jn57x3aheam.avif",g="/ai/daily/2026-06-18/news_01kvcbmtfrexzb9jnev40ag9wz.avif",m="/ai/daily/2026-06-18/news_01kvcbmwgpexzb9jnhb8nb6dtt.avif",u="/ai/daily/2026-06-18/news_01kvccwyxxexzb9jrqx5yhf2wa.avif",x=JSON.parse('{"title":"AI大事件 2026/6/18","description":"AI大事件 2026/6/18 - 陈老板的百宝箱 AI 大事件日报，追踪模型发布、AI 产品、前沿研究、开源工具、安全政策与行业动态。","frontmatter":{"linkTitle":"06-18 AI大事件","title":"AI大事件 2026/6/18","weight":14,"breadcrumbs":false,"comments":true,"description":""},"headers":[],"relativePath":"ai/daily/cn/2026-06/2026-06-18.md","filePath":"AI/daily/cn/2026-06/2026-06-18.md","lastUpdated":1781755924000}'),b={name:"ai/daily/cn/2026-06/2026-06-18.md"};function f(k,a,_,A,q,I){return o(),r("div",null,[...a[0]||(a[0]=[t(`<h1 align="center">2026-06-18 AI大事件</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Midjourney、Cursor、Vercel、Google 与 OpenAI 延续产品和智能体工具更新，创作、编码、语音与云端协作继续加速 🚀</span></span>
<span class="line"><span>GLM-5.2、AMIE、LifeSciBench、SDR 和化学智能体线索显示，研究侧正在同时推进基准、医学、数据防御与科学发现 🧠</span></span>
<span class="line"><span>OpenAI 财务数据、G7 AI 治理、美国对华制裁节奏与苹果硬件成本，把 AI 竞赛推向更强的产业和政策张力 ⚖️</span></span>
<span class="line"><span>OpenMontage、UI-TARS、codebase-memory-mcp 与 TimesFM 等开源工具，继续把多模态、代码索引和时间序列能力下沉到开发者手里 🛠️</span></span>
<span class="line"><span>Google A2UI/MCP Apps、Gemini 3.5 Pro 预告和 GPT-Realtime-2 语音交互，让“智能体如何接入真实界面”成为今天的重点 ( •̀ ω •́ )</span></span>
<span class="line"><span>今天的主线是：模型能力继续外溢到产品、硬件、治理和开源生态，落地速度越快，验证和成本纪律越重要 (๑•̀ㅂ•́)و✧</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-cursor-编译器更新云端智能体环境" tabindex="-1">1. Cursor 编译器更新云端智能体环境 <a class="header-anchor" href="#_1-cursor-编译器更新云端智能体环境" aria-label="Permalink to &quot;1. Cursor 编译器更新云端智能体环境&quot;">​</a></h3><p>Cursor 将云端沙箱带进智能体窗口，开发者可以把更重的改写、测试和检查任务交给远端环境处理 ☁️。这降低了本地配置门槛，也让团队协作中的代码代理更容易保持一致执行环境。 来源：<a href="https://cursor.com/changelog/cloud-in-agents-window" target="_blank" rel="noreferrer">Cursor</a></p><h3 id="_2-vercel-发布开源-ai-智能体框架-eve-每个智能体就是一个文件目录" tabindex="-1">2. Vercel 发布开源 AI 智能体框架 Eve：每个智能体就是一个文件目录 <a class="header-anchor" href="#_2-vercel-发布开源-ai-智能体框架-eve-每个智能体就是一个文件目录" aria-label="Permalink to &quot;2. Vercel 发布开源 AI 智能体框架 Eve：每个智能体就是一个文件目录&quot;">​</a></h3><p>Vercel 发布开源 AI 智能体框架 Eve（npm 包，Apache-2.0 许可）。Eve 采用文件系统优先设计：每个智能体对应一个磁盘目录，目录结构直接映射模型、指令、工具、技能、连接、子智能体等能力。框架内置持久执行、沙箱计算、人机审批、安全连接、多通道入口和追踪评估，适合把企业内部智能体从原型推进到生产环境 🚀。 来源：<a href="https://www.marktechpost.com/2026/06/17/vercel-releases-eve/" target="_blank" rel="noreferrer">MarkTechPost</a></p><h3 id="_3-cursor-重磅发布-origin-欲重塑开发生态" tabindex="-1">3. Cursor 重磅发布 Origin 欲重塑开发生态 <a class="header-anchor" href="#_3-cursor-重磅发布-origin-欲重塑开发生态" aria-label="Permalink to &quot;3. Cursor 重磅发布 Origin 欲重塑开发生态&quot;">​</a></h3><p>Cursor 重磅发布 代码编辑器发布代码托管平台 欲重塑代码托管。 该产品专为 AI 智能体 高频协作 🚀 场景而深度定制开发。 它支持每小时八万次推送 😱 完美解决多智能体合并冲突。 开发者在 IDE 内 (๑•̀ㅂ•́)و✧ 即可完成从代码编写到评审全闭环。 这项 基础设施级更新 标志着 重新书写人机协作新标准 底层基建的诞生。 来源：<a href="https://cursor.com/origin-waitlist" target="_blank" rel="noreferrer">Cursor</a></p><p><img src="`+n+'" alt="AI资讯：Cursor推出的Origin代码协作平台界面截图" loading="lazy"></p><h3 id="_4-molmomotion-语言引导的-3d-运动预测模型" tabindex="-1">4. MolmoMotion：语言引导的 3D 运动预测模型 <a class="header-anchor" href="#_4-molmomotion-语言引导的-3d-运动预测模型" aria-label="Permalink to &quot;4. MolmoMotion：语言引导的 3D 运动预测模型&quot;">​</a></h3><p>MolmoMotion 基于 Molmo 2 骨干网络，输入视频帧、物体上的 3D 点标记及文字动作指令（如“移动并旋转桌上放水果的木碗”），预测未来数秒内这些点的 3D 轨迹。提供两个变体：自回归的 MolmoMotion-AR 逐步预测坐标，流匹配的 MolmoMotion-FM 通过连续空间变换处理多可能性运动。同时发布 MolmoMotion-1M 数据集（含 116 万视频的 3D 点轨迹及动作描述）和 PointMotionBench 基准测试（2700 个人工验证视频片段）。模型权重、数据集和基准测试均已开源。 🚀 来源：<a href="https://huggingface.co/blog/allenai/molmomotion" target="_blank" rel="noreferrer">Hugging Face</a></p><h3 id="_5-grok-4-3-在-amazon-bedrock-正式可用" tabindex="-1">5. Grok 4.3 在 Amazon Bedrock 正式可用 <a class="header-anchor" href="#_5-grok-4-3-在-amazon-bedrock-正式可用" aria-label="Permalink to &quot;5. Grok 4.3 在 Amazon Bedrock 正式可用&quot;">​</a></h3><p>6 月 17 日，xAI 宣布 Grok 4.3 在 Amazon Bedrock 上全面可用。该模型在前沿模型中达成最低幻觉率，支持 100 万 token 上下文窗口，并提供可配置推理努力（none/low/medium/high）。在 Artificial Analysis Omniscience 基准排名第一，在 Tau2 Telecom 基准评估客服智能体真实工具调用性能排名第一，在 Vals AI Case Law 和 Corporate Finance 基准的复杂文档理解任务排名第一。定价为输入每百万 token 1.25 美元、输出每百万 token 2.50 美元，每美元智能度是其他前沿模型的 2–10 倍。 🚀 来源：<a href="https://x.ai/news/grok-amazon-bedrock" target="_blank" rel="noreferrer">x.ai</a></p><h3 id="_6-wolfram-语言和-mathematica-15-版发布-内置-ai-助手、符号音乐等新功能" tabindex="-1">6. Wolfram 语言和 Mathematica 15 版发布：内置 AI 助手、符号音乐等新功能 <a class="header-anchor" href="#_6-wolfram-语言和-mathematica-15-版发布-内置-ai-助手、符号音乐等新功能" aria-label="Permalink to &quot;6. Wolfram 语言和 Mathematica 15 版发布：内置 AI 助手、符号音乐等新功能&quot;">​</a></h3><p>在 Mathematica 诞生近 38 年后，Wolfram 语言与 Mathematica 发布 Version 15。新版在每个笔记本中内置 AI 助手，新增符号音乐系统、大规模时间序列与事件序列处理、分类数据计算和模型拟合超函数 ModelFit。它还加强了 WebSocket、Python 交互、表格连接和可视化能力，继续把计算语言扩展成更完整的研究与工程工作台 🛠️。 来源：<a href="https://writings.stephenwolfram.com/2026/06/launching-version-15-of-wolfram-language-mathematica-built-in-useful-ai-lots-of-new-core-functionality" target="_blank" rel="noreferrer">writings.stephenwolfram.com</a></p><h3 id="_7-阿里云发布-happyoyster-1-0-一句话生成可实时交互的数字世界" tabindex="-1">7. 阿里云发布 HappyOyster 1.0：一句话生成可实时交互的数字世界 <a class="header-anchor" href="#_7-阿里云发布-happyoyster-1-0-一句话生成可实时交互的数字世界" aria-label="Permalink to &quot;7. 阿里云发布 HappyOyster 1.0：一句话生成可实时交互的数字世界&quot;">​</a></h3><p>6 月 17 日，阿里云发布开放式世界模型 HappyOyster 1.0（快乐生蚝）。该产品基于原生多模态架构，支持多模态输入与音视频联合生成，可在生成过程中持续接收用户指令并实时响应画面。它深度学习物理世界状态转移规律，保持人物和环境长程一致性。官网开放“实时导演”与“世界探索”两种玩法：前者可随时叫停改写故事、与虚拟男友实时互动等；后者支持自由漫游、滑板冲刺、翼装滑翔、骑马奔驰、攻击打怪等交互。该产品已于今年 4 月 16 日开放内测，即日起至 7 月 17 日官网不定期掉落体验积分。 🚀 来源：<a href="https://www.ithome.com/0/965/652.htm" target="_blank" rel="noreferrer">ithome.com</a></p><h3 id="_8-claude-design-更新-跨项目保持品牌一致-与-claude-code-协同" tabindex="-1">8. Claude Design 更新：跨项目保持品牌一致，与 Claude Code 协同 <a class="header-anchor" href="#_8-claude-design-更新-跨项目保持品牌一致-与-claude-code-协同" aria-label="Permalink to &quot;8. Claude Design 更新：跨项目保持品牌一致，与 Claude Code 协同&quot;">​</a></h3><p>6 月 17 日，Claude Design 更新，支持跨项目使用统一设计系统，并与 Claude Code 同步工作流。用户可直接拖拽、对齐和缩放画布元素，编辑器稳定性大幅提升。设计系统可从 GitHub、设计文件或原始上传导入，团队管理员可锁定标准系统防止篡改。新增桌面端侧边栏入口及独立网页端 claude.ai/design。使用限制与聊天、Claude Cowork、Claude Code 共享，每次任务消耗更少 token，错误率下降。支持导出 PDF、PPT，集成 Adobe、Canva、Gamma 等工具。发布首周用户超一百万。 🚀 来源：<a href="https://claude.com/blog/claude-design-stays-on-brand-for-daily-work" target="_blank" rel="noreferrer">claude.com</a></p><h3 id="_9-strands-robots-sdk-用单一智能体打通-hugging-face-hub-到物理机器人" tabindex="-1">9. Strands Robots SDK：用单一智能体打通 Hugging Face Hub 到物理机器人 <a class="header-anchor" href="#_9-strands-robots-sdk-用单一智能体打通-hugging-face-hub-到物理机器人" aria-label="Permalink to &quot;9. Strands Robots SDK：用单一智能体打通 Hugging Face Hub 到物理机器人&quot;">​</a></h3><p>AWS（Apache 2.0）开源的 Strands Robots SDK 将 LeRobot 栈封装为 AgentTools，构建统一智能体。默认用 MuJoCo 模拟（无需硬件），mode=&quot;real&quot; 切换至真实机器人。可记录演示数据为 LeRobotDataset 并推送 Hugging Face Hub，运行 GR00T 或 LerobotLocal 策略推理，经 Zenoh mesh 广播命令到多台机器人。模拟与硬件代码完全一致，只需改一个关键字参数。示例可在笔记本（Python 3.12+，Linux/macOS）无硬件、无 GPU 运行。 🚀 来源：<a href="https://huggingface.co/blog/amazon/strands-lerobot-hub-to-hardware" target="_blank" rel="noreferrer">Hugging Face</a></p><h3 id="_10-绘图软件发布全新草图模式" tabindex="-1">10. 绘图软件发布全新草图模式 <a class="header-anchor" href="#_10-绘图软件发布全新草图模式" aria-label="Permalink to &quot;10. 绘图软件发布全新草图模式&quot;">​</a></h3><p>官方今日重磅推出了 多图预览功能 😲。新机制能一口气跑出 24 张低清图。这让算力消耗直接 💰 降低至标准版一半。遇到完美创意可一键 ✨ 生成最终高清稿。这种高效抽卡玩法对设计人员极为友好。 🚀 来源：<a href="https://updates.midjourney.com/draft-mode-for-v8-1-and-new-feature-previews/" target="_blank" rel="noreferrer">Midjourney</a></p><p><img src="'+i+'" alt="AI资讯：Midjourney图像工具草图模式在画布上快速生成的二十四宫格低清晰度绘图作品预览" loading="lazy"></p><h3 id="_11-glm-5-2-登顶开源榜首" tabindex="-1">11. GLM 5.2 登顶开源榜首 <a class="header-anchor" href="#_11-glm-5-2-登顶开源榜首" aria-label="Permalink to &quot;11. GLM 5.2 登顶开源榜首&quot;">​</a></h3><p>智谱全新开源模型 刷新多项纪录。 它在 Vals Index 表现 🚀 惊艳。 编程能力 直逼 Opus 4.7 模型 ( •̀ ω •́ )。 该 开源之光 位列全球总榜第五名。 开发者 💻 都能免费体验顶级算力。 来源：<a href="https://huggingface.co/blog/zai-org/glm-52-blog" target="_blank" rel="noreferrer">Hugging Face</a></p><p><img src="'+l+'" alt="AI资讯：GLM 5.2 模型在多项基准测试中排名全球前五的对比图表" loading="lazy"></p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-全新-rl-算法打破自回归魔咒" tabindex="-1">1. 全新 RL 算法打破自回归魔咒 <a class="header-anchor" href="#_1-全新-rl-算法打破自回归魔咒" aria-label="Permalink to &quot;1. 全新 RL 算法打破自回归魔咒&quot;">​</a></h3><p>研究中心正式拉开了 E³RL 算法 🌀 序幕。科学家借助 突破推理魔咒 解决难题。其局部熵算法 💡 能精准锁定认知不确定性。模型借助缓存机制 (っ•̀ω•́) 实现极速纠错。这成功帮助自愈式大模型拓宽了研究基座。 🧠 来源：<a href="https://arxiv.org/abs/2606.17735" target="_blank" rel="noreferrer">arXiv</a></p><h3 id="_2-数据清洗防御技术-sdr-正式发布" tabindex="-1">2. 数据清洗防御技术 SDR 正式发布 <a class="header-anchor" href="#_2-数据清洗防御技术-sdr-正式发布" aria-label="Permalink to &quot;2. 数据清洗防御技术 SDR 正式发布&quot;">​</a></h3><p>这篇针对 大模型洗白数据识别 的研究走红。针对换样式隐藏 😠 侵权的行为提供解决方案。其检测算法能通过逆向逆策略精准还原篡改。方案在 Llama 等模型 🔍 上已截获海量问题样本。这给今后的版权审计提供了强大底层技术。 🧠 来源：<a href="https://arxiv.org/abs/2604.01904" target="_blank" rel="noreferrer">arXiv</a></p><h3 id="_3-审计框架助力治理大模型幻觉" tabindex="-1">3. 审计框架助力治理大模型幻觉 <a class="header-anchor" href="#_3-审计框架助力治理大模型幻觉" aria-label="Permalink to &quot;3. 审计框架助力治理大模型幻觉&quot;">​</a></h3><p>团队发表 虚假信息检测方案 攻克行业难题。它在合同处理中 (๑•̀ㅂ•́) 能划分维度识别。全新计算指标 ⚖️ 帮助检测微弱的逻辑偏差。配合智能体多轮辩论 🚀 让虚假率下降四成。这为合规法律助手 ( •̀ ω •́ ) 落地扫清了障碍。 🧠 来源：<a href="https://arxiv.org/abs/2606.18021" target="_blank" rel="noreferrer">arXiv</a></p><h3 id="_4-技术报告展示高品质合成数据集" tabindex="-1">4. 技术报告展示高品质合成数据集 <a class="header-anchor" href="#_4-技术报告展示高品质合成数据集" aria-label="Permalink to &quot;4. 技术报告展示高品质合成数据集&quot;">​</a></h3><p>科学家公布了 计算机智能体报告 最新成果。新合成数据集拥有 ✨ 超三百万高质量优质样本。系统利用大模型可实现 (๑•̀ㅂ•́) 全自动任务生成。智能体在基准评测大胜且执行成功率狂飙。这展现了控制 💡 操作系统软件的广阔应用。 🧠 来源：<a href="https://huggingface.co/papers/2606.17321" target="_blank" rel="noreferrer">Hugging Face</a></p><p><img src="'+s+'" alt="AI资讯：ProCUA技术报告中描绘的使用多层级合成数据集在大模型桌面环境下全自动训练智能体的逻辑框架图" loading="lazy"></p><h3 id="_5-知名开发框架遭遇安全漏洞" tabindex="-1">5. 知名开发框架遭遇安全漏洞 <a class="header-anchor" href="#_5-知名开发框架遭遇安全漏洞" aria-label="Permalink to &quot;5. 知名开发框架遭遇安全漏洞&quot;">​</a></h3><p>研究人员警告 Handlebars 🧐 存在命令注入。攻击者伪造特殊定界符 即可突破安全限制。该漏洞会触发 😱 权限提升及未授权指令执行。主流模型在 🛡️ 调试测试中几乎频繁翻翻车。广大开发者们 (ヘ･_･) 记得尽早做好数据隔离。 🧠 来源：<a href="https://arxiv.org/abs/2606.18120" target="_blank" rel="noreferrer">arXiv</a></p><h3 id="_6-用-sglang-jax-在-tpu-上优化-ling-2-6-1t-一个-pallas-核将-moe-数据移动隐藏在计算中" tabindex="-1">6. 用 SGLang-JAX 在 TPU 上优化 Ling-2.6-1T：一个 Pallas 核将 MoE 数据移动隐藏在计算中 <a class="header-anchor" href="#_6-用-sglang-jax-在-tpu-上优化-ling-2-6-1t-一个-pallas-核将-moe-数据移动隐藏在计算中" aria-label="Permalink to &quot;6. 用 SGLang-JAX 在 TPU 上优化 Ling-2.6-1T：一个 Pallas 核将 MoE 数据移动隐藏在计算中&quot;">​</a></h3><p>SGLang-JAX 现已支持 inclusionAI 的 Ling-2.6-1T 在 TPU v7x 上高效推理。团队开发的 Fused MoE V2 Pallas 核融合 scatter、专家 FFN 和 gather，把 MoE 数据移动隐藏进计算过程，使预填充延迟从 5.16ms 降至 2.42ms，解码核延迟从 0.249ms 降至 0.211ms。仅替换 MoE 核就带来 24.8% 的预填充吞吐提升和 18.5%–35.3% 的解码吞吐提升 🧠。 来源：<a href="https://www.lmsys.org/blog/2026-06-17-ling-2-6-tpu" target="_blank" rel="noreferrer">lmsys.org</a></p><h3 id="_7-lifescibench-发布" tabindex="-1">7. LifeSciBench 发布 <a class="header-anchor" href="#_7-lifescibench-发布" aria-label="Permalink to &quot;7. LifeSciBench 发布&quot;">​</a></h3><p>2026 年 6 月，OpenAI 联合 173 位博士级生命科学家发布 LifeSciBench 评测基准，涵盖 750 个真实研究任务，覆盖证据处理、分析、设计优化等七个工作流及七个生物领域。每项任务配有约 25 条细化评分标准（共 19,020 条），评估模型的科学正确性与实用价值。79% 的任务需多步推理，53% 要求解读图表、PDF 等附件数据，旨在衡量 AI 在复杂、不确定的研究任务中的实际能力，而非仅回答结构化问题。 🧠 来源：<a href="https://openai.com/index/introducing-life-sci-bench" target="_blank" rel="noreferrer">OpenAI</a></p><h3 id="_8-google-医学推理-ai-系统-amie-新研究-从诊断迈向长期疾病管理" tabindex="-1">8. Google 医学推理 AI 系统 AMIE 新研究：从诊断迈向长期疾病管理 <a class="header-anchor" href="#_8-google-医学推理-ai-系统-amie-新研究-从诊断迈向长期疾病管理" aria-label="Permalink to &quot;8. Google 医学推理 AI 系统 AMIE 新研究：从诊断迈向长期疾病管理&quot;">​</a></h3><p>今日发表在《自然》杂志上的研究展示了 Google 的医学推理 AI 系统 AMIE（Articulate Medical Intelligence Explorer）从单次诊断对话演进到长期疾病管理的能力。AMIE 利用 Gemini 模型的长上下文能力，整合共情对话智能体和深度思考管理推理智能体，可交叉引用数百页临床指南。在盲测中，AMIE 与 21 名初级保健医生相比，在整体管理推理上匹配临床医生，在计划精确性和指南一致性上得分显著更高。 🧠 来源：<a href="https://blog.google/innovation-and-ai/models-and-research/google-research/amie-for-disease-management-in-nature" target="_blank" rel="noreferrer">Google Blog</a></p><h3 id="_9-openai-与-molecule-one-合作-gpt‐5-4-自主优化-chan‐lam-偶联反应" tabindex="-1">9. OpenAI 与 Molecule.one 合作：GPT‑5.4 自主优化 Chan‑Lam 偶联反应 <a class="header-anchor" href="#_9-openai-与-molecule-one-合作-gpt‐5-4-自主优化-chan‐lam-偶联反应" aria-label="Permalink to &quot;9. OpenAI 与 Molecule.one 合作：GPT‑5.4 自主优化 Chan‑Lam 偶联反应&quot;">​</a></h3><p>OpenAI 将 GPT‑5.4 接入 Molecule.one 的自主化学智能体 Maria，用于优化药物化学中的 Chan‑Lam 偶联反应。GPT‑5.4 独立识别伯磺酰胺为高价值挑战性底物，并建议使用 TEMPO 等温和氧化剂。经两轮实验，88% 的硼酸和 83% 的磺酰胺底物产率提升，平均产率从 16.6% 升至 25.2%，产率超 30% 的反应占比从 15.6% 增至 37.5%。人类化学家后续验证，14 对底物中 11 对产率提高，多数提升超两倍。 🧠 来源：<a href="https://openai.com/index/ai-chemist-improves-reaction" target="_blank" rel="noreferrer">OpenAI</a></p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-我国正加速建立国际智能组织" tabindex="-1">1. 我国正加速建立国际智能组织 <a class="header-anchor" href="#_1-我国正加速建立国际智能组织" aria-label="Permalink to &quot;1. 我国正加速建立国际智能组织&quot;">​</a></h3><p>有关部门加速筹建 世界智能合作组织。该多边机构将 🚀 引导多国统一 技术标准。新闻发布会多次提到健康和 安全治理 (๑•̀ㅂ•́)。此方案将极大展现我们在人工智能的责任担当。多国现已表明了会深入配合并加入进来。 来源：<a href="https://english.cctv.com/2026/06/17/ARTIGaqZjRRo1aliq8I05NgB260617.shtml" target="_blank" rel="noreferrer">english.cctv.com</a></p><h3 id="_2-泄露文件显示-openai-年营收-130-亿但亏损远超收入" tabindex="-1">2. 泄露文件显示 OpenAI 年营收 130 亿但亏损远超收入 <a class="header-anchor" href="#_2-泄露文件显示-openai-年营收-130-亿但亏损远超收入" aria-label="Permalink to &quot;2. 泄露文件显示 OpenAI 年营收 130 亿但亏损远超收入&quot;">​</a></h3><p>OpenAI 2025 年营收 130.7 亿美元（2024 年 37 亿），但研发成本达 191.8 亿（含向微软支付 105.9 亿），收入成本（推理计算）75 亿，销售营销成本 57.3 亿，运营亏损 209.2 亿。2025 年净亏损约 390 亿，扣除约 300 亿一次性会计费用后约 80 亿。2025 年 3 月获 1220 亿融资（估值 8520 亿）。ChatGPT 周活超 9 亿，付费约 5000 万。为控制成本已关闭 Sora 视频模型并削减非核心业务。 来源：<a href="https://arstechnica.com/ai/2026/06/leaked-financial-docs-show-openai-is-losing-billions-of-dollars-a-year" target="_blank" rel="noreferrer">arstechnica.com</a></p><h3 id="_3-消息称-openai-今年一季度现金消耗达-37-亿美元-超同期收入的一半" tabindex="-1">3. 消息称 OpenAI 今年一季度现金消耗达 37 亿美元，超同期收入的一半 <a class="header-anchor" href="#_3-消息称-openai-今年一季度现金消耗达-37-亿美元-超同期收入的一半" aria-label="Permalink to &quot;3. 消息称 OpenAI 今年一季度现金消耗达 37 亿美元，超同期收入的一半&quot;">​</a></h3><p>OpenAI 在 2026 年第一季度现金消耗达 37 亿美元，超过同期 57 亿美元收入的一半。数据来自一份向股东披露的文件，直观体现 AI 大模型研发与规模化落地的巨额成本。OpenAI 正筹备上市，已在美国保密递交 IPO 申请，最早或于 9 月完成，估值最高可达 1 万亿美元。头部 AI 企业持续重金投入算力、模型研发与人才招募以维持竞争优势。 来源：<a href="https://www.ithome.com/0/965/335.htm" target="_blank" rel="noreferrer">ithome.com</a></p><h3 id="_4-中国加紧筹建世界人工智能合作组织" tabindex="-1">4. 中国加紧筹建世界人工智能合作组织 <a class="header-anchor" href="#_4-中国加紧筹建世界人工智能合作组织" aria-label="Permalink to &quot;4. 中国加紧筹建世界人工智能合作组织&quot;">​</a></h3><p>中国正加紧筹建世界人工智能合作组织，欢迎各方加入。2025 年 7 月 26 日，中国政府倡议成立该组织，作为践行多边主义、推动共商共建共享全球治理的举措，旨在弥合数字和智能鸿沟、促进人工智能向善普惠发展。初步考虑总部设在上海。同日，2025 世界人工智能大会发表《人工智能全球治理行动计划》，呼吁各方遵循向善为民、尊重主权、发展导向、安全可控、公平普惠、开放合作的原则，协力推进全球人工智能发展与治理。 来源：<a href="https://www.ithome.com/0/965/248.htm" target="_blank" rel="noreferrer">ithome.com</a></p><h3 id="_5-谷歌发布-agentic-resource-discovery-ard-开放规范" tabindex="-1">5. 谷歌发布 Agentic Resource Discovery（ARD）开放规范 <a class="header-anchor" href="#_5-谷歌发布-agentic-resource-discovery-ard-开放规范" aria-label="Permalink to &quot;5. 谷歌发布 Agentic Resource Discovery（ARD）开放规范&quot;">​</a></h3><p>Agentic Resource Discovery（ARD）是一项开放规范，用于在 Web 上发布、发现和验证 AI 工具、技能与智能体。它基于两个原语：组织在其自有域名下托管 catalog 描述可用能力，registry 作为搜索引擎索引 catalog 并响应发现请求。ARD 支持加密验证，使客户端与端点连接前确认发布者身份，然后直接通过原生协议调用能力。Google Cloud 的 Gemini Enterprise Agent Platform 通过 Agent Registry 提供企业级支持，包括 URN 命名、出站策略、工具固定和基于 Agent Identity 的信任验证。该规范现已发布，开发者可通过托管<code>ai-catalog.json</code>文件使其服… 来源：<a href="https://developers.googleblog.com/announcing-the-agentic-resource-discovery-specification" target="_blank" rel="noreferrer">Google Developers Blog</a></p><h3 id="_6-databricks-扩大对-snowflake-的领先优势" tabindex="-1">6. Databricks 扩大对 Snowflake 的领先优势 <a class="header-anchor" href="#_6-databricks-扩大对-snowflake-的领先优势" aria-label="Permalink to &quot;6. Databricks 扩大对 Snowflake 的领先优势&quot;">​</a></h3><p>Databricks 年化经常性收入（ARR）达 69 亿美元，同比增长 80%；同期 Snowflake ARR 约 53 亿美元，增速 34%。两者差距从 3 月的 4.9 亿美元扩大至 16 亿美元。AI 产品年化收入 17 亿美元，占总 ARR 的 25%，六个月前为 10 亿美元。Salesforce 以 36 亿美元收购 Fin，其 AI 智能体年收入 1 亿美元，同样占比约 25%，同比增长 350%。Databricks 私人估值 1340 亿美元，80% 的增长率远超 CrowdStrike（26%）和 Shopify（34%）等同行。 来源：<a href="https://www.tomtunguz.com/databricks-widens-lead" target="_blank" rel="noreferrer">tomtunguz.com</a></p><h3 id="_7-claude-opus-4-8-build-day-黑客马拉松获奖项目揭晓" tabindex="-1">7. Claude Opus 4.8 Build Day 黑客马拉松获奖项目揭晓 <a class="header-anchor" href="#_7-claude-opus-4-8-build-day-黑客马拉松获奖项目揭晓" aria-label="Permalink to &quot;7. Claude Opus 4.8 Build Day 黑客马拉松获奖项目揭晓&quot;">​</a></h3><p>6 月 13 日，Anthropic 在旧金山举办 12 小时黑客马拉松，310 名参与者使用 Opus 4.8 和$500 credits 完成原型。第一名 Tekton：输入历史建筑照片后，Claude 自动搜集图纸等资料，跨 339 个施工步骤重建 3D 模型，每个构件附带证据链；自纠循环反复检查直至 20 项测试全部通过。第二名 Sim Francisco：基于美国人口普查数据生成 10,000 名合成市民，各具独立世界观，实时对新闻投票，精准预测选举结果。第三名 Custom Universe：用手机拍摄物件照片，Opus 4.8 将其转为可拖放、实时渲染的 3D 物体，支持文本指令重设风格。 来源：<a href="https://claude.com/blog/meet-the-winners-of-our-claude-opus-4-8-build-day-hackathon" target="_blank" rel="noreferrer">claude.com</a></p><h3 id="_8-anthropic-在首尔开设办公室并宣布多项韩国-ai-生态合作" tabindex="-1">8. Anthropic 在首尔开设办公室并宣布多项韩国 AI 生态合作 <a class="header-anchor" href="#_8-anthropic-在首尔开设办公室并宣布多项韩国-ai-生态合作" aria-label="Permalink to &quot;8. Anthropic 在首尔开设办公室并宣布多项韩国 AI 生态合作&quot;">​</a></h3><p>Anthropic 正式启用首尔办公室，并宣布与韩国 AI 生态的多项合作。NAVER、Nexon、LG CNS、Hanwha Solutions、Samsung SDS 和 Channel Corp 都在不同场景中部署 Claude、Claude Code 或相关企业方案。这个动作说明 Claude 的企业落地正在从美国市场扩展到东亚大型集团与开发者生态 ☁️。 来源：<a href="https://www.anthropic.com/news/seoul-office-partnerships-korean-ai-ecosystem" target="_blank" rel="noreferrer">Anthropic</a></p><h3 id="_9-智能服务成本飙升或致硬件涨价" tabindex="-1">9. 智能服务成本飙升或致硬件涨价 <a class="header-anchor" href="#_9-智能服务成本飙升或致硬件涨价" aria-label="Permalink to &quot;9. 智能服务成本飙升或致硬件涨价&quot;">​</a></h3><p>库克近日直言 苹果 AI 成本压力 已不可持续。超负荷的 计算资源 😱 正压缩公司的毛利。全球广大消费者 (；′⌒`) 担心设备售价上升。上游硬件核心 🚀 供应链的供货价也面临调整。如何解决算力能耗将成未来科技巨头新考卷。 来源：<a href="https://techcrunch.com/2026/06/17/ai-is-hurting-apple-in-more-ways-than-one-it-may-force-iphone-price-increases/" target="_blank" rel="noreferrer">TechCrunch</a></p><h3 id="_10-anthropic-与-deepmind-ceo-呼吁-g7-组建-ai-联盟排除中国" tabindex="-1">10. Anthropic 与 DeepMind CEO 呼吁 G7 组建 AI 联盟排除中国 <a class="header-anchor" href="#_10-anthropic-与-deepmind-ceo-呼吁-g7-组建-ai-联盟排除中国" aria-label="Permalink to &quot;10. Anthropic 与 DeepMind CEO 呼吁 G7 组建 AI 联盟排除中国&quot;">​</a></h3><p>Dario Amodei（Anthropic）与 Demis Hassabis（Google DeepMind）在 G7 闭门会议上呼吁组建美国主导的联盟，为人工智能制定全球规则和标准。Amodei 指出，该联盟应以前沿模型和硬件（包括芯片及其他关键组件）的访问权限为手段，将中国排除在外。这一主张被评论为高技术新冷战的开端，竞争方将从根本上被剥夺参与权。 来源：<a href="https://pluang.com/en/news-feed/ceo-anthropic-google-deepmind-serukan-koalisi-ai-pimpin-as-g7" target="_blank" rel="noreferrer">CNBC 转引</a></p><p><img src="'+c+'" alt="AI资讯：Dario与Demis提议组建美国领导的排他性AI标准的社交平台推文" loading="lazy"><img src="'+h+'" alt="AI资讯：G7高级闭门会议中关于限制关键硬件和前沿算力技术流向的文案截图" loading="lazy"></p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-智能视频生产系统全套代码开源-🌟5k" tabindex="-1">1. 智能视频生产系统全套代码开源 🌟5k <a class="header-anchor" href="#_1-智能视频生产系统全套代码开源-🌟5k" aria-label="Permalink to &quot;1. 智能视频生产系统全套代码开源 🌟5k&quot;">​</a></h3><p>新系统能让开发者把电脑变身 影视工作室。它内置了五十二种 🎬 高能影视生成工具。快来学习 视频生产框架 获取最新代码。工具目前已斩获了 ⭐5k 标星。其剪辑效率 (⊙o⊙) 确实让同行感到不可思议。 🛠️ 来源：<a href="https://github.com/calesthio/OpenMontage" target="_blank" rel="noreferrer">GitHub</a></p><p><img src="'+p+'" alt="AI资讯：OpenMontage自动化AI视频剪辑生产全工作流的可视化操作面板示意图" loading="lazy"></p><h3 id="_2-字节跳动开源多模态桌面智能体-🌟36k" tabindex="-1">2. 字节跳动开源多模态桌面智能体 🌟36k <a class="header-anchor" href="#_2-字节跳动开源多模态桌面智能体-🌟36k" aria-label="Permalink to &quot;2. 字节跳动开源多模态桌面智能体 🌟36k&quot;">​</a></h3><p>字节推出了强大的 UI-TARS 桌面级工具。用户可 连接前沿模型 自动化电脑操作。新平台 🚀 能够帮用户解放双手处理繁琐杂事。此框架在 GitHub 斩获 ⭐3.6w 个点赞。传统的桌面办公体验 😲 接下来要发生改变了。 🛠️ 来源：<a href="https://github.com/bytedance/UI-TARS-desktop" target="_blank" rel="noreferrer">GitHub</a></p><p><img src="'+d+'" alt="AI资讯：字节跳动UI-TARS开源桌面端多模态控制智能体软件运行界面的核心模块逻辑图" loading="lazy"></p><h3 id="_3-全新代码索引内存服务器开源" tabindex="-1">3. 全新代码索引内存服务器开源 <a class="header-anchor" href="#_3-全新代码索引内存服务器开源" aria-label="Permalink to &quot;3. 全新代码索引内存服务器开源&quot;">​</a></h3><p>该服务在开发者社区中 🚀 引起了狂热关注。它能一键把代码库 🤯 毫秒级转为 核心知识图谱。该插件竟完美支持 158 种 常用编程语言。它运行极快 (๑•̀ㅂ•́) 且最快节省九成算力费。项目实现了零依赖运行而且十分的轻量。 🛠️ 来源：<a href="https://github.com/DeusData/codebase-memory-mcp" target="_blank" rel="noreferrer">GitHub</a></p><p><img src="'+g+'" alt="AI资讯：高性能代码索引服务codebase-memory-mcp将杂乱无章的源代码解析成知识图谱的流程图" loading="lazy"></p><h3 id="_4-谷歌推出全新时序预测模型-🌟20k" tabindex="-1">4. 谷歌推出全新时序预测模型 🌟20k <a class="header-anchor" href="#_4-谷歌推出全新时序预测模型-🌟20k" aria-label="Permalink to &quot;4. 谷歌推出全新时序预测模型 🌟20k&quot;">​</a></h3><p>大厂推出了最新的 时序模型仓库 来攻克商业预测。其在开源平台 📈 狂揽了两万多星标点赞。针对时序处理痛点 💡 谷歌首创预训练方案。相比传统数理方法 ✨ 模型精度有了跨越提升。开发者可以直接调用其实现高效率生产。 🛠️ 来源：<a href="https://github.com/google-research/timesfm" target="_blank" rel="noreferrer">GitHub</a></p><p><img src="'+m+'" alt="AI资讯：谷歌研究室TimesFM预训练时间序列预测大模型的网络结构设计与趋势预测对比图" loading="lazy"></p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-google-分享-a2ui-与-mcp-apps-三种集成架构模式" tabindex="-1">1. Google 分享 A2UI 与 MCP Apps 三种集成架构模式 <a class="header-anchor" href="#_1-google-分享-a2ui-与-mcp-apps-三种集成架构模式" aria-label="Permalink to &quot;1. Google 分享 A2UI 与 MCP Apps 三种集成架构模式&quot;">​</a></h3><p>Google 分享了三种集成 A2UI 与 MCP Apps 的架构模式，旨在结合两者优势。A2UI 采用声明式框架，通过 JSON payload 定义 UI，由宿主原生渲染，确保一致性与安全性，但受限于预定义组件库。MCP Apps 在 iframe 中使用标准 Web 技术提供自定义界面，但存在设计碎片化、性能与安全挑战。三种模式包括：通过 MCP 服务器提供 A2UI，利用 MCP Resources 或 Tool 调用传递 JSON，实现“一次编写，原生渲染”的跨平台能力；以及静态与动态交付方案。Google 正考虑扩展 MCP 以原生支持 A2UI。 ( •̀ ω •́ ) 来源：<a href="https://developers.googleblog.com/a2ui-and-mcp-apps" target="_blank" rel="noreferrer">Google Developers Blog</a></p><h3 id="_2-博客现状-2026-年中" tabindex="-1">2. 博客现状，2026 年中 <a class="header-anchor" href="#_2-博客现状-2026-年中" aria-label="Permalink to &quot;2. 博客现状，2026 年中&quot;">​</a></h3><p>Nathan Lambert 在 Interconnects 博客创办约三年后更新规划。他当前三大目标：为前沿模型演进提供清晰度、创建开放模型生态、建立支撑机构。博客定位为原始、高辨识度的独立声音，避免成为全职分析平台。已披露与 Arcee AI 和 Mercor 签署咨询协议，以深入后训练领域并推动透明评测与开放生态。订阅者突破 7 万，付费约 900 人；运营实体 Interconnects AI, LLC 已成立，但银行账户数月余额接近零，收入再投入业务，近期不打算全职运营。 ( •̀ ω •́ ) 来源：<a href="https://www.interconnects.ai/p/state-of-the-blog-mid-2026" target="_blank" rel="noreferrer">interconnects.ai</a></p><h3 id="_3-gemini-3-5-pro-发布在即" tabindex="-1">3. Gemini 3.5 Pro 发布在即 <a class="header-anchor" href="#_3-gemini-3-5-pro-发布在即" aria-label="Permalink to &quot;3. Gemini 3.5 Pro 发布在即&quot;">​</a></h3><p>谷歌暗示 Gemini 3.5 Pro 就要来了 🚀 谷歌最新模型爆料 视觉能力 🧐 变得更强啦。 前端生成功能这次会升级到 新高度。 虽然模型定价 💰 可能会贵不少滴。 ( •̀ ω •́ ) 希望官方把 偷懒问题 彻底改掉。 来源：<a href="https://cloud.google.com/blog/products/ai-machine-learning/innovations-from-google-io-26-on-google-cloud" target="_blank" rel="noreferrer">Google Cloud Blog</a></p><p><img src="'+u+'" alt="AI资讯：谷歌Gemini 3.5 Pro产品宣传卡片展示图" loading="lazy"></p><h3 id="快讯" tabindex="-1">快讯 <a class="header-anchor" href="#快讯" aria-label="Permalink to &quot;快讯&quot;">​</a></h3><ul><li><strong>微软研究员在复古游戏中测试 AI 底层逻辑</strong>：大牛在帝国时代 2 游戏中用山羊羊群搭建了电路。点击了解这个 有趣的底层实验 成果和初衷。该项目旨在戳穿学界 🐐 严重的拟人化偏见。即便把模型换成山羊 ╮(￣ ▽ ￣)╭ 逻辑也不变。论文深刻指出当前半数研究过分夸大了机器智能。 来源：<a href="https://the-decoder.com/microsoft-researcher-builds-a-working-neural-network-out-of-goats-in-age-of-empires-ii-to-critique-ai-science/" target="_blank" rel="noreferrer">the-decoder.com</a></li><li><strong>知名智能框架惨遭依赖包注入致命后门</strong>：流行开发组件意外遭遇大规模供应链注入。黑客成功在 一百多个恶意包 植入 (≧ 口 ≦) 特殊后门。此次投毒导致 😱 数百下游项目沦为了重灾区。开发者切莫大意必须 🛠️ 急速清扫所有的包安全。防范未然是 AI 应用顺利部署的长久根基。 来源：<a href="https://www.stepsecurity.io/blog/mastra-npm-packages-compromised-using-easy-day-js" target="_blank" rel="noreferrer">stepsecurity.io</a></li><li><strong>奥特曼与达里奥同台现身 G7 峰会</strong>：奥特曼与 达里奥 在 G7 峰会 👔 罕见同桌聚餐。 美国限制了 最强模型出口 ⛔ 动作真快。 这种自相茅盾的行为 😅 让现场盟友们感到很尴尬。 地缘政治 🌐 成了左右顶级模型扩散的核心因素。 未来的 技术竞赛 将演变成权力博弈 (•̀ω•́)✧。 来源：<a href="http://bloom.bg/4edq2wa" target="_blank" rel="noreferrer">bloom.bg</a></li><li><strong>预训练还不够“苦涩”</strong>：CMU 文章重新审视 Richard Sutton 的“苦涩教训”：现代预训练采用通用架构和海量数据，但训练目标仍由人类在粗粒度循环外选择。作者关注的是能否让这个控制环路更高效、更少依赖手工试错。 来源：<a href="https://blog.ml.cmu.edu/2026/06/17/pre-training-isnt-bitter-enough" target="_blank" rel="noreferrer">blog.ml.cmu.edu</a></li><li><strong>特朗普向 Anthropic 提出不可能的要求</strong>：Gary Marcus 借 Anthropic 安全争议讨论生成式 AI 护栏困境：系统很难在过严与过松之间取得稳定平衡。文章认为问题不只属于一家模型公司，而是当前 next-token predictor 范式的治理难题。 来源：<a href="https://garymarcus.substack.com/p/breaking-trump-asks-the-impossible" target="_blank" rel="noreferrer">garymarcus.substack.com</a></li><li><strong>GPT-Realtime-2 定义未来</strong>：开发者西蒙斯展示出 ⚡️ 实时语音 OS 的全新交互形态。 用户可凭借口语 语音控制电脑系统 效率挺高。 这种 深度系统集成 仅需几个提示词就能搞定 (⊙o⊙)。 未来的 人机交互 似乎真的不再需要键盘了 🚀。 来源：<a href="https://openai.com/index/advancing-voice-intelligence-with-new-models-in-the-api/" target="_blank" rel="noreferrer">OpenAI</a></li></ul><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>产品竞争正在转成工作流竞争。</strong> Cursor Origin、Vercel Eve、Google A2UI/MCP Apps 和 GPT-Realtime-2 都在把模型能力嵌进更具体的协作界面 🚀。</li><li><strong>开源模型和评测继续互相拉动。</strong> GLM-5.2、LifeSciBench、SDR 等线索说明，能力叙事正在被更细的任务基准和可复现实验重新校准 🧠。</li><li><strong>AI 成本会外溢到硬件和公司财务。</strong> OpenAI 财务披露与苹果涨价压力都提醒市场：推理、内存和资本开支不是抽象变量 💰。</li><li><strong>治理议题更加地缘化。</strong> G7 会议、美国对华技术管制和国际 AI 组织建设，正在把模型访问权、标准和供应链绑定在一起 ⚖️。</li><li><strong>开发者工具仍是最快落地层。</strong> OpenMontage、UI-TARS、codebase-memory-mcp 与 TimesFM 展示了多模态生产、桌面控制、代码知识图谱和预测模型的实际抓手 🛠️。</li></ul>',96)])])}const y=e(b,[["render",f]]);export{x as __pageData,y as default};
